def solve(n: int, L: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    cr = ClassicalRegister(n, "out")
    qc.append(qc.x, range(n))
    qc.h(range(n))
    qc.barrier()

    for i in range(1, n):
        for j in range(2**i, 2**(i+1)):
            for k in range(j, 2**n, 2**i):
                qc.cx(k, k+i)

    qc.measure(range(n), cr)

    if L > 1:
        extra_amplitudes = 2**(n - 1) - L + 1
        qc.x(range(n))[extra_amplitudes:]

    return qc

