def solve(n: int, L: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    for i in range(n):
        for j in range(1, 2**i):
            qc.cx(i, i+j)

    # Apply Hadamard gates to even-numbered qubits
    for i in range(n):
        if i % 2 == 0:
            qc.h(i)

    # Invert the first qubit (if L is not 1)
    if L > 1:
        qc.x(0)

    # Apply Hadamard gates to odd-numbered qubits (if L > 2^(n-1))
    if L > 2**(n-1):
        for i in range(1, n):
            if i % 2 == 1 and 2**(i-1) < L <= 2**i:
                qc.h(i)

    # Reverse the first qubits for L < 2^(n-1)
    if L < 2**(n-1):
        for i in range(1, n):
            qc.cx(i, 0)

    # Adjust the last qubit for L < 2^n
    if L < 2**n:
        qc.x(n-1)

    return qc

