def solve(n: int, L: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    oracle = GroverOracle(n, L)

    # Apply T-gate, controlled-U, and Hadamard gates
    for _ in range(len(oracle.to_gate())):
        qc.append(oracle.to_gate(), range(n))
        qc.barrier()

    # Adjust the last qubit for L < 2^n
    if L < 2**n:
        qc.x(n-1)

    # Adjust the last qubits for L < 2^(n-1)
    if L < 2**(n-1):
        for i in range(n-2, -1, -1):
            if L < 2**(i+1):
                qc.x(i)
                break

    return qc

