from sympy import powmod

@functools.lru_cache(maxsize=128)
def fast_mod_pow(base, exp, mod):
    if exp == 0:
        return 1
    if exp % 2 == 1:
        return powmod(base, exp, mod) * powmod(base, exp - 1, mod) * powmod(base, mod - 2, mod) % mod
    half_result = fast_mod_pow(base, exp // 2, mod)
    return powmod(half_result, 2, mod)

def solve(n: int, a: int, L: int) -> list[int]:
    result = [None] * n
    result[0] = fast_mod_pow(a, 1, L)
    for i in range(1, n):
        result[i] = fast_mod_pow(result[i - 1] * result[i - 1], 2, L)
    return result

def extended_euclidean(a: int, b: int) -> List[int]:
    previous_x, x = 0, 1
    previous_y, y = 1, 0
    temp1, temp2: List[int] = []
    while b != 0:
        temp1.append((a % b, previous_x % b))
        temp2.append((-previous_y % b, x - (previous_y * (a // b))))
        a, b = b, a % b
        x, previous_x = previous_x, x
        y, previous_y = previous_y, y
    return list(reversed(temp1)) + temp2

def modular_inverse(a: int, m: int) -> int:
    x, _ = extended_euclidean(a, m)
    if x < 0:
        x += m
    return x

def solve(a: int, L: int) -> int:
    return modular_inverse(a, L)

